        /// <summary>每行：id、名字、命途、元素、角色详情、价格。</summary>
        public static readonly string[][] Rows = new string[][]
        {
            new[] { "acheron", "黄泉", "虚无", "雷", "自称「巡海游侠」的旅人，本名不详。身佩一柄长刀，独行银河。；；淡漠寡言，剑出如紫电般迅猛，却从来只以刀鞘战斗，收而不发。", "809" },
            new[] { "aglaea", "阿格莱雅", "记忆", "雷", "在那黎明照拂的圣城，织者抚弄金丝，连缀命运。；「金织」阿格莱雅，背负「浪漫」火种的黄金裔，你要召集世间英雄，带领他们再度踏上漫长的征程；——击落众神，归还神火，予以几近覆灭的翁法罗斯新生。", "602" },
            new[] { "anaxa", "那刻夏", "智识", "风", "神悟树庭，滋养知识的学府，诞育哲人的摇床。；但渎神的阿那克萨戈拉斯，诘问「理性」火种的黄金裔，试问：你甘愿身负恶名，也要违逆预言，将怀疑的枝杈刺入智慧的圣树？；——<i>「可笑。这世界遍地虚假，唯有我才是真实。」</i>", "1048" },
            new[] { "archer", "Archer", "巡猎", "量子", "绝望轮番上演于过去与未来之间，无数理想曾在红色圣骸布之间燃尽。但，请别被这一抹灰烬欺骗——；若是有人假借理想之名营造虚幻的美梦，他必将再度燃烧，与世间的伪善战斗到底。；无论身在何处，他始终是正义的伙伴。", "798" },
            new[] { "argenti", "银枝", "智识", "物理", "「纯美骑士团」的古典骑士。；他为人正直、光明磊落，高贵的天性令人敬佩——一位游走宇宙间的独行者，坚定践行「纯美」。；维护「纯美」在宇宙间的名誉，是银枝的职责：履行这一义务，起手需虔诚，落枪时则将要令人心悦诚服。", "787" },
            new[] { "arlan", "阿兰", "毁灭", "雷", "不善言辞的空间站「黑塔」防卫科负责人。；虽然不懂科研，但为了保护珍视研究的空间站科员顺利完成他们的研究，阿兰可以拼上性命。他早已习惯疼痛，并将负伤视作勋章。；也只有抱着佩佩时，男孩才会放下戒备，露出难得一见的笑容。", "1037" },
            new[] { "ashveil", "不死途", "巡猎", "雷", "随缘营业，硬核推理，全凭直觉却屡破奇案。；猴子当助手，一心盼退休，侦探睡在冰箱，只为等愿者上钩。；幻月下，恶兽长嗥，他的追猎游戏会如何收网？", "363" },
            new[] { "asta", "艾丝妲", "同谐", "火", "好奇心与精力都很旺盛的少女，空间站「黑塔」的名义站长。；无论是管理各抒己见的科员，还是直接又不失礼貌地回复博识学会的种种刁难，对艾丝妲来说都易如反掌。；毕竟指挥空间站…总比继承家业简单吧！", "776" },
            new[] { "aventurine", "砂金", "存护", "虚数", "星际和平公司「战略投资部」的高级干部，「石心十人」之一，基石为「诡弈砂金」。；个性张扬的风险爱好者，时常面带笑容，真心却难以揣测。 ；靠着同命运的博弈赢得如今的地位，将人生视作一场高风险、高回报的投资，而他向来游刃有余。", "1026" },
            new[] { "aventurine_waveflair", "砂金•戏浪", "欢愉", "量子", "盛典点亮海岸，风暴于狂欢中酝酿。；接过密令，他再度站到风口浪尖，搅动悠长假日——；当险浪吞没身影，他又将如何破局？", "1015" },
            new[] { "bailu", "白露", "丰饶", "雷", "性格活泼的小女孩，持明族的「衔药龙女」，药到病除的名医。；经常开出不拘一格的药方，如「多喝热水」、「睡一觉就好了」。；见不得人受苦，治病时总是闭着眼睛。；——总之病好了就行！", "765" },
            new[] { "black_swan", "黑天鹅", "虚无", "风", "「流光忆庭」的忆者，神秘优雅的占卜师。；常挂着温柔的微笑，耐心聆听他人的言语，并借此走入「记忆」，掌握全盘信息。；热衷于收集独一无二的记忆，背后的想法却难以看透。", "1200" },
            new[] { "blade", "刃", "毁灭", "风", "弃身锋刃的剑客，原名不详。；效忠于「命运的奴隶」，拥有可怖的自愈能力。；手持古剑作战，剑身遍布破碎裂痕，正如其身，亦如其心。", "591" },
            new[] { "boothill", "波提欧", "巡猎", "物理", "浪迹银河的改造人牛仔，极度乐观、放荡不羁。；身为「巡海游侠」的一员，为惩奸除恶，可以无所不用其极——；高调行事的背后，渴望以此引起复仇对象「星际和平公司」的注意。", "580" },
            new[] { "bronya", "布洛妮娅", "同谐", "风", "贝洛伯格「大守护者」继承人，年轻干练的银鬃铁卫统领。；布洛妮娅从小接受着严格的教育，具备一名「继承人」所需的优雅举止与亲和力。；但在看到下层区的恶劣环境后，未来的最高决策者逐渐生出了疑惑…「我所受的训练，真的能带领人民过上他们想要的生活么？」", "1189" },
            new[] { "castorice", "遐蝶", "记忆", "量子", "那敬爱死亡的国度，终日飘雪的哀地里亚，今日已沉入甘甜的酣眠。；冥河的女儿遐蝶，寻索「死亡」火种的黄金裔，启程吧。你要呵护世间魂灵的恸哭，拥抱命运的孤独；——生死皆为旅途，当蝴蝶停落枝头，那凋零的又将新生。；", "1004" },
            new[] { "cerydra", "刻律德菈", "同谐", "风", "北境帝国，失落的王朝，寒冷的疆土燃烧着征伐的野心。；君主刻律德菈，执握「律法」火种的黄金裔，你要布局设子，与神相弈，审判异心的罪囚，为此世奠定逐火的基业；——「这绝非终点，翁法罗斯的征途，当是银河群星！」", "993" },
            new[] { "cipher", "赛飞儿", "虚无", "量子", "失落的盗寇之都多洛斯，三百侠盗纵情游戏，横行无忌。；捷足的贼星赛法利娅，戏弄「诡计」火种的黄金裔，奔走吧。愿你的谎言随风同行，吹遍此世大地；——「呵，还想诓我？没门！」", "983" },
            new[] { "clara", "克拉拉", "毁灭", "物理", "被机器人养大的女孩，有着超越年龄的通透和坚持。；对克拉拉而言，史瓦罗理性的计算是世界法则，绝不会出错。；直到发现「计算」得到的结果，并不一定能带给大家幸福。；怯生生的女孩决定勇敢起来。", "754" },
            new[] { "cyrene", "昔涟", "记忆", "冰", "流星划过夜空，生命的长河荡起涟漪，闪烁十三种光彩。；哀丽秘榭的女儿，哺育「真我」的黄金裔，你要栽下记忆的种子，让往昔的花朵在明日绽放；——「然后，一起写下不同以往的诗篇吧♪」", "1178" },
            new[] { "dan_heng", "丹恒", "巡猎", "风", "清冷寡言的少年，持有名为「击云」的长枪，于列车漫长的开拓之旅中担任护卫。；丹恒对自己的过往始终讳莫如深，他与列车同行正是为了摆脱自己曾亲手造就的一切。；然而，列车真的会带着他远离「过去」么？", "352" },
            new[] { "dan_heng_imbibitor", "丹恒•饮月", "毁灭", "虚数", "丹恒接纳了上一世「饮月君」所遗存的力量，所展露的持明族本相。；既然接受了额顶的峥嵘角冠，便也要接受那人所负的一切功过。；但从始至终，他都不是他。", "972" },
            new[] { "dan_heng_tenghuang", "丹恒•腾荒", "存护", "物理", "吉奥里亚的胸膛，伏龙的身躯支撑破碎的大地，忍耐千年苦痛。；无名客丹恒，捍卫「大地」火种的黄金裔，你要扶八荒之将倾，将地上生灵送往远方的天地；——百川归海，群山合鸣，不朽的道途将绵延万里。", "961" },
            new[] { "dr_ratio", "真理医生", "巡猎", "虚数", "直率而自我的博识学会学者，常以奇怪的石膏头雕遮蔽面容。；自幼便展露出过人的才智，如今却以「庸人」自居。；坚信智慧与创造力并不为天才独有，致力于向全宇宙传播知识，医治名为愚钝的顽疾。", "743" },
            new[] { "evanescia", "绯英", "欢愉", "物理", "一季幻月满盈，一季人世更迭，神秘少女再度现身二相乐园！；落英易散，她的停留也不过刹那。新时代的一切令她痴迷，绝不容许有人破坏——；一把尺刀裁定正邪，可谁又能知，己身善恶几何？", "570" },
            new[] { "evernight", "长夜月", "记忆", "冰", "与世相隔的忆域，烛火映出过往，于迷雾中悄然熄去。；自那影中而来的记忆之子长夜月，隐匿「岁月」火种的黄金裔，你要掀起「忘却」的浪潮，守护镜中人的心愿；——「别担心，我会为你看护『开拓』的前路…不惜任何代价♭」", "1167" },
            new[] { "feixiao", "飞霄", "巡猎", "风", "仙舟「曜青」的天击将军，帝弓七天将之一，为人不拘一格，率直潇洒。；精通百般武艺，炼化躯体至极致，享有「大捷将军」美名，深受仙舟军民爱戴。；但身负「月狂」之症，如要在时限内猎尽孽物——飞霄唯一的敌手，便是自己。", "950" },
            new[] { "firefly", "流萤", "毁灭", "火", "星核猎手成员，身着机械装甲「萨姆」战斗。忠于任务，性格坚强。；作为战胜虫群的兵器而诞生，其生长速度异于常人，但生命非常短暂。；为了找寻「生」的机会而加入星核猎手，找寻违抗命运的方式。", "559" },
            new[] { "fu_xuan", "符玄", "存护", "量子", "仙舟「罗浮」太卜司之首，自信耿直的智者。；凭借第三眼与穷观阵为仙舟占算航路，预卜事务吉凶，坚信自己所做的一切便是事情的「最优解」。；符玄等待着将军承诺的「退位让贤」，然而这一天的到来…似乎还遥遥无期。", "548" },
            new[] { "fugue", "忘归人", "虚无", "火", "八面玲珑的狐人少女，样貌、名字、身份皆被人夺去。；命运为她留下一线生机，而「毁灭」的烙印仍在蠢蠢欲动。；历经生死、重获新生的忘归人，何时才能返乡？", "733" },
            new[] { "gallagher", "加拉赫", "丰饶", "火", "匹诺康尼猎犬家系的治安官，也是一位不修边幅、懒散随性的调饮师。；着装颇为散漫，调饮更是随意，对来访宾客以礼相待，但保有戒心。；似乎有着诸多往事，却从不主动提及。", "939" },
            new[] { "gepard", "杰帕德", "存护", "冰", "高洁正直的银鬃铁卫戍卫官，出身于血脉高贵的朗道家族。；在时刻遭受风雪侵凌的贝洛伯格，人们的衣食住行尚能如旧——；正是因为杰帕德与他率领的银鬃铁卫在守护这平淡无奇的日常生活。", "341" },
            new[] { "gilgamesh", "吉尔伽美什", "毁灭", "雷", "在宇宙之外的某个世界中，人类历史最初的英雄王。；三分之二是神、三分之一是人的他，理所当然地拥有支配一切的特权（自称）。；今天也一如既往地放声大笑着，直到被某个世仇女神牵连进异界——；这一次，他将再次夺回身为王的一切。", "1157" },
            new[] { "guinaifen", "桂乃芬", "虚无", "火", "因机缘巧合留在仙舟的化外民，如今是热情烂漫的街头艺人。；本名「格妮薇儿」，「桂乃芬」是好友素裳为她起的仙舟名。；面对「罗浮」的全新人生，凭着对仙舟文化的热爱，桂乃芬很快学到了安身立命的一技之长——倒立吃面条、胸口碎大石、徒手接子弹等等。", "330" },
            new[] { "hanya", "寒鸦", "同谐", "物理", "仙舟「罗浮」的十王司判官之一，负责拘、锁、刑、问的四判官中的「问」。；专司读取犯人的因果罪愆，而后以「冥谶天笔」书写业报判罚。；由于整日使用梦占形式工作，承受着巨量魔阴身因果信息的冲刷，早已对世间万事感到索然无味。；只有与同为判官的姐姐雪衣行动时，才会流露片刻的真心。", "537" },
            new[] { "herta", "黑塔", "智识", "冰", "空间站「黑塔」真正的主人。；身为湛蓝星智商最高的人类，只做自己感兴趣的事，一旦失去兴趣就立刻走人——空间站就是最好的例子。；平时以远程操纵的人偶形态登场：「跟我小时候比，勉强七分相似吧。」——黑塔本人。", "1146" },
            new[] { "himeko", "姬子", "智识", "火", "充满冒险精神的科学家，少女时代在故乡遭遇了搁浅的星穹列车。；彼时，列车内的某种存在向她展示了身处的星球之外，名为「宇宙」的世界。；若干年后，当姬子终于修复列车驶入群星时，她意识到这只是个开始。在「开拓」新世界的道路上，需要更多的同伴——；即使同行的人们面朝不同的方向，他们仍处于同一片星空下。", "320" },
            new[] { "himeko_nova", "姬子•启行", "智识", "火", "有人并肩，有人守望，「开拓」从不是孤帆远航。；她画下拓星的奇迹，银轨绵延，无名客们再次起航，照亮星河的长夜——终点处，她再度回望，启行的梦从未搁浅。", "1135" },
            new[] { "hook", "虎克", "毁灭", "火", "冒险集团「鼹鼠党」的头头，自称「漆黑的虎克大人」。；不喜欢被人称作小家伙，认为自己不依靠大人也能独挡一面。；大人们去裂界里冒险，桑博先生去地面上冒险，病人们冒险接受娜塔莎的治疗…在虎克的带领下，孩子们也要有自己的冒险！", "309" },
            new[] { "huohuo", "藿藿", "丰饶", "风", "可怜又弱小的狐人小姑娘，也是怕鬼捉鬼的罗浮十王司见习判官。；名为「尾巴」的岁阳被十王司的判官封印在她的颀尾上，使她成为了招邪的「贞凶之命」。；害怕妖魔邪物，却总是受命捉拿邪祟，完成艰巨的除魔任务；；自认能力不足，却无法鼓起勇气辞职，只好默默害怕地继续下去。", "722" },
            new[] { "hyacine", "风堇", "记忆", "风", "云间城邦随岁月离析，昏光庭院再度敞开门扉，为永夜捎来微光。；医师雅辛忒丝，守望「天空」火种的黄金裔。你要继承先祖的意志，缝补破裂的晨昏；——愿虹光洒落，仇怨消融，黎明重回大地。", "928" },
            new[] { "hysilens", "海瑟音", "虚无", "物理", "斯缇科西亚，醉与梦的海滨之城，旧日的歌声仍在浮浪间回荡。；大海的女儿海列屈拉，清洗「海洋」火种的黄金裔，你要驱散污浊的暗流，为天外的英雄奏响不醉不归的盛宴；——散场之时未到，纵然希望如泡沫般易碎，浪花也将一往无前。", "711" },
            new[] { "jade", "翡翠", "智识", "量子", "星际和平公司「战略投资部」的高级干部，「石心十人」之一，基石为「典贷翡翠」。；冷艳优雅的放贷人，善于洞悉人心，有着名为「慈玉典押」的个人爱好。；愿意为获取高价值的事物耐心等待，也擅长从看似一无所有的客户身上榨取价值。", "526" },
            new[] { "jiaoqiu", "椒丘", "虚无", "火", "仙舟「曜青」的狐人医士、策士，常以笑脸迎人，实际颇有心计。；出身于丹鼎司名家，曾一度心死避世，不再行医，后为医治「天击将军」飞霄再度出山。；精于医食同源的丹方研究，尤其是能带给人痛感的辣味食物，发明了名为「九宫格」的鼎镬药式。", "515" },
            new[] { "jing_yuan", "景元", "智识", "雷", "位列帝弓七天将之一的「神策将军」，外表懒散、心思缜密。不以危局中力挽狂澜为智策，因此在常事上十分下功夫，以免节外生枝。因其细心谋划，仙舟承平日久，看似行事慵懒的景元反被送上绰号「闭目将军」。", "504" },
            new[] { "jingliu", "镜流", "毁灭", "冰", "传奇「云上五骁」之一，人送尊号「无{{注音|罅|xià}}飞光」。；超脱了人间的胜负，为了获得斩杀「神」的力量，她选择走上截然不同的道路。；至此之后，仙舟的记录中少了一个罗浮「剑首」，多了一个名字被抹去的「叛徒」。", "493" },
            new[] { "kafka", "卡芙卡", "虚无", "雷", "在星际和平公司的通缉档案里，卡芙卡只留下了名字和「爱好收集大衣」的记录。人们对这位星核猎手所知甚少，只知道她是「命运的奴隶」艾利欧最信任的成员之一。； 为了到达艾利欧预见的「未来」，卡芙卡开始行动。", "700" },
            new[] { "lingsha", "灵砂", "丰饶", "火", "仙舟「罗浮」丹鼎司新任司鼎，伶俐秀慧的持明医士。；嗅觉敏锐，常以此识别病症，并以香薰安定他人心神。；善于处理混杂的人际关系，即使心底暴躁如雷，表面上依旧滴水不漏。", "917" },
            new[] { "luka", "卢卡", "虚无", "物理", "乐观阳光、不拘小节的机械臂自由格斗家，「地火」成员之一。；从拳台到战场，从拳击手到战士，卢卡用这份力量去守护下层区的人们。；正因为自己曾经体会过绝望，所以他更渴望将希望带给其他人。", "483" },
            new[] { "luocha", "罗刹", "丰饶", "虚数", "金发俊雅的年轻人，背着巨大的棺椁。；身为天外行商的他，不幸被卷入仙舟罗浮的星核危机。；一手精湛医术莫名有了用武之地。", "1124" },
            new[] { "lynx", "玲可", "丰饶", "量子", "朗道家年龄最小的女孩，贝洛伯格首屈一指的极地探险家。；看似慵懒，实际上执行力极强。散发生人勿近的气场只是为了避免不必要的社交。；至于如何定义不必要的社交——「呃…所有社交不都是没必要的吗？」", "472" },
            new[] { "march_7th_hunt", "三月七•巡猎", "巡猎", "虚数", "换上仙舟服饰的三月七，执剑的武侠少女。；向云璃与彦卿拜师学艺，为在仙舟留下更多美好的「回忆」而跃跃欲试。", "298" },
            new[] { "march_7th_preservation", "三月七•存护", "存护", "冰", "精灵古怪的少女，自认热衷于这个年纪的女孩子「应当热衷」的所有事，比如照相。；从一块漂流的恒冰中苏醒，却发现自己对身世与过往都一无所知。短暂的消沉之后，她决定以重获新生的日期为自己命名。；这一天，三月七「诞生」了。", "1113" },
            new[] { "misha", "米沙", "毁灭", "冰", "乖巧懂事的「白日梦酒店」门童，梦想成为一名和爷爷一样的银河冒险家。；工作十分努力，尤其擅长修理各类机械，热衷于酒店住客分享的星际见闻。；希望自己快快长大，期待着早日有一天踏上探索群星的旅程。", "689" },
            new[] { "mortenax_blade", "千冶•刃", "虚无", "火", "身如春木，心若死灰，指尖仍留工匠的火星。；累世宿怨再度点燃，他许诺将自己与神明一同送往彼岸——；支离此身，千冶成刃…会铸就何种答案？", "907" },
            new[] { "moze", "貊泽", "巡猎", "雷", "仙舟「曜青」的影卫，沉默寡言、独来独往。；专司情报与不见光的事务，鲜少在人前露面。貊泽显露锋芒时，便是敌人的死期。；刺杀手段丰富，对整洁和条理有超乎寻常的执着。", "287" },
            new[] { "mydei", "万敌", "毁灭", "虚数", "那沉入迷雾的悬锋，纷乱与战争之城！它的王室流着弑亲的血脉，它的神明以灾厄为名。；不死的迈德漠斯，离群的狮子，逐猎「纷争」火种的黄金裔。你要忍受万死，浴血还乡，孤身背负疯狂的宿命——弑王成王，弑神登神。征战的铁蹄踏遍荒野，终归要沾上故乡的血。", "896" },
            new[] { "natasha", "娜塔莎", "丰饶", "物理", "做事严谨的医生，总带着难以捉摸的微笑。；在医疗资源匮乏的下层区，娜塔莎作为为数不多的医生照料着地下的男女老幼。；即使是最调皮的虎克，见了她也要乖乖喊一声「娜塔莎姐姐」。", "461" },
            new[] { "pearl", "真珠", "欢愉", "冰", "点染星月，描摹万象，文明的遗珠重焕光彩。；因解析艺术而诞生，她追寻美的极境，却从未失却「存护」的底色：；历经洗礼，她会收获怎样的「真珠」？", "1102" },
            new[] { "pela", "佩拉", "虚无", "冰", "行事周密的银鬃铁卫情报官，年纪不大但头脑出众。；无论是部队调动、物资分配还是地形状况，佩拉都能冷静地即问即答，毫无错漏。；至于佩拉的手机壳…「这与工作无关，长官。」", "276" },
            new[] { "phainon", "白厄", "毁灭", "物理", "哀丽秘榭，遗世独立的边陲村落，如今只余晦涩的传说。；无名的英雄卡厄斯兰那，容纳「负世」火种的黄金裔，你要铭记全世的理想，背负万众的命运，为新世界带来第一缕曙光；——「但倘若黎明从不存在，就让怒火燃尽此身，化作明日的烈阳！」", "678" },
            new[] { "qingque", "青雀", "智识", "量子", "太卜司的普通卜者，在「忙里偷闲」这件事上绝不偷闲。；顺应父母的期望考入太卜司，却发现本以为清闲的铁饭碗是高强度的职场苦海。；经过数年历练，青雀终于磨砺了一身本领——无论部门流转，她仍旧是最低职级的卜者。；没事翻翻书，玩玩古代牌戏…人生如此，夫复何求？", "1091" },
            new[] { "rappa", "乱破", "智识", "虚数", "如丑时三刻的闪光弹一般现身在匹诺康尼，以忍者自居，将世间一切归因于「忍法」的奇妙少女。；贯彻吟诵忍•真言、绘制缭乱•忍符、修习忍•法帖的「忍•道」——即说唱，涂鸦，漫画——苦炼自身意志，驰骋星间行侠仗义。；身为「巡海游侠」的一员，始终追猎着名为「御猿•邪忍」的恶党，直至银河尽头。", "1080" },
            new[] { "rin_tohsaka", "远坂凛", "智识", "量子", "来自宇宙之外，某个存在着魔法与魔术的世界，不断精进自我的少女魔术师——冬木市魔术世家，远坂家第六代当家。；如今师从于「时钟塔」某位与圣杯战争颇有渊源的名师，为了完成实习课题穿梭于次元与位面之间……；「欸？这里是哪？？怎么一点魔力都没有啊？？？；「圣、圣杯？有救了！不好意思，借我一用！」", "1070" },
            new[] { "robin", "知更鸟", "同谐", "物理", "出生于匹诺康尼，闻名银河的天环族歌者，举止从容优雅的少女。；此次受家族宴请回到故乡，在「谐乐大典」为众宾献歌一曲。；可以依靠「同谐」的力量传递歌声，在歌迷乃至万界生灵之中展现「共鸣」。", "265" },
            new[] { "robin_summeretto", "知更鸟•晴歌", "记忆", "风", "飞越晴空蓝海，羽翼掠起浪花，化作新声。；循着回忆的遗音，她拥抱一路意外，寻觅变奏的灵感——；谐乐之外，「同谐」还能怎样歌唱？", "667" },
            new[] { "ruan_mei", "阮•梅", "同谐", "冰", "气质温婉优雅的学者，「天才俱乐部」#81号会员，生命科学领域的专家。；凭借天赋与惊人的执著得到了博识尊的瞩目，在秘密的角落开始了对生命本源的研究与探索。；并因此被黑塔邀请，同螺丝咕姆、斯蒂芬联合开发了「模拟宇宙」。；私下里，她十分喜爱传统戏剧与点心，对刺绣也很感兴趣。", "450" },
            new[] { "saber", "Saber", "毁灭", "风", "孤独的英灵走过命运的长夜， 圆桌的旗帜仍在梦中舒展。卡美洛的骑士之王，此时尚未抵达理想乡。；仍是少女的她于这场特殊的「圣杯战争」中应召前来，当再度面临石中剑的抉择，她将如何突破过往的幻境？；——「我未实现的愿望，也将在此作结。」", "657" },
            new[] { "sampo", "桑博", "虚无", "风", "口若悬河的倒货商人，只要有「利」的地方，就有桑博的身影。；桑博手中绝无仅有的情报让人不得不接近他，不过成为他的「客人」并不是什么好事。；毕竞只要价钱合适，「客人」也随时可以转化为「商品」。", "439" },
            new[] { "seele", "希儿", "巡猎", "量子", "飒爽俊逸的「地火」成员，成长于地底危险混乱的环境，习惯独来独往。；保护与被保护，压迫与被压迫，世界向希儿展示的始终是非黑即白的那一面——；直至「那名少女」的出现。", "885" },
            new[] { "serval", "希露瓦", "智识", "雷", "自由叛逆的朗道家长女，曾是可可利亚的挚友，如今是兴趣使然的机械师。；在永冬的贝洛伯格经营着名为「永动」的机械屋，时不时停业举办摇滚露天演出。；如果有人过问机械屋怎么赚钱…「这是兴趣，亲爱的，我不缺钱。」", "428" },
            new[] { "silver_wolf", "银狼", "虚无", "量子", "将宇宙视为游戏的超级骇客。；无论怎样棘手的防御系统，银狼都能轻松破解。她与「天才俱乐部」螺丝咕姆的数据攻防战，现已成为骇客界的传说。；宇宙中还有多少亟待攻破的关卡？银狼对此十分期待。", "874" },
            new[] { "silver_wolf_lv_999", "银狼LV.999", "欢愉", "虚数", "新一轮欢愉赛季，无敌玩家「银狼LV.999」限时回归中！；成为宇宙大赢家，银河通关全成就，接下来还要怎么玩？；<i>「走上『欢愉』巅峰？无聊到爆好嘛…既然卡带到手，就我说了算咯~」</i>", "646" },
            new[] { "sparkle", "花火", "同谐", "量子", "「假面愚者」的成员之一，难以捉摸，不择手段。；危险的戏剧大师，沉迷于扮演，身怀千张假面，能化万种面相。；财富、地位、权力…于花火而言都不重要，能让她出手的，唯有「乐趣」。", "863" },
            new[] { "sparxie", "火花", "欢愉", "火", "点赞！关注！直播！流量！狂欢直到世界尽头！；火花和花火，假面与愚者本无不同——；谁被看见，谁被喜欢，谁就是正确答案！", "852" },
            new[] { "sunday", "星期日", "同谐", "虚数", "「秩序」的美梦已然消散，但仍有人不会放下初愿。；——折翼坠地的旅人，他的脚步将迈向何方？", "841" },
            new[] { "sushang", "素裳", "巡猎", "物理", "单纯热心的云骑军新人，执一柄重剑。；憧憬着云骑军历史上的传奇，渴望成为响当当的人物。；为此，素裳坚决格守「急人所急，有求必应；日行一善，三省吾身」的信条，过着助人为乐的忙碌日子。", "254" },
            new[] { "the_dahlia", "大丽花", "虚无", "火", "美梦燃烧了永火官邸，也带走关于「她」的点滴。；；「毁灭」、「记忆」…背叛的花朵盛放在所经之地——；；重返无人知晓的梦境，将她再度点燃的会是何方？", "417" },
            new[] { "the_herta", "大黑塔", "智识", "冰", "尊贵的「天才俱乐部」#83，人类，女性，年轻，貌美，可爱。；传说她隐居在银河边境，几乎不踏出其间，想必此次现身——；一定是为了某个不得不亲自出马的问题吧？", "407" },
            new[] { "tingyun", "停云", "同谐", "雷", "八面玲珑的狐人少女，天舶司商团「鸣火」的首席代表。；停云天生生得一副慧心妙舌，但凡她开口，人们就免不了想听她多说几句。在她的调度下，仙舟的贸易庆典逐渐声名远扬。；能不战斗就尽量不去战斗，能劝为己用就尽量劝为己用——这便是停云的原则。", "243" },
            new[] { "topaz_and_numby", "托帕&账账", "巡猎", "火", "星际和平公司旗下「战略投资部」高级干部托帕，领导特殊债务纠察小组。；年纪轻轻便已成为「石心十人」之一，基石为「催讨黄玉」。；搭档次元扑满「账账」则能敏锐感知「财富」所在，即便是安保、催债、精算等工作也不在话下。；如今他们正一同巡行银河，追究各类影响公司业务开展的债务纠纷。", "396" },
            new[] { "trailblazer_destruction", "开拓者•毁灭", "毁灭", "物理", "登上星穹列车的少女/少年。；为了消除星核带来的危机，选择与星穹列车同行。", "635" },
            new[] { "trailblazer_elation", "开拓者•欢愉", "欢愉", "雷", "欢笑吧，哭泣吧，诅咒吧，赞美吧！；狂欢至死的时代，众声喧哗。成为英雄或跌落神坛，只在瞬息之间。；「欢愉」的无数面相，最终被拾起的会是哪一副？", "830" },
            new[] { "trailblazer_harmony", "开拓者•同谐", "同谐", "虚数", "登上星穹列车的少女/少年。；为了消除星核带来的危机，选择与星穹列车同行。", "233" },
            new[] { "trailblazer_preservation", "开拓者•存护", "存护", "火", "登上星穹列车的少女/少年。；为了消除星核带来的危机，选择与星穹列车同行。", "222" },
            new[] { "trailblazer_remembrance", "开拓者•记忆", "记忆", "冰", "向着未知启航的开拓者，与新的伙伴「迷迷」一同，书写下翁法罗斯的旅途见闻——；而「记忆」也将生生不息，铺就远行的旅路，记录壮丽的诗篇。", "211" },
            new[] { "tribbie", "缇宝", "同谐", "量子", "自那三相神谕垂怜的圣地，信使分作千身，启程远行。；雅努萨波利斯的圣女，缇里西庇俄丝，窃夺「门径」火种的黄金裔，你要为众生奔走，令救世的讯息晓喻大地——找寻那流淌黄金神血的人子，冲破世间至暗，去往星月满天的明日。", "200" },
            new[] { "welt", "瓦尔特", "虚无", "虚数", "老成持重的前逆熵盟主，继承了「世界」之名，曾屡次拯救世界于灭亡的边缘。；圣方丹事件结束后，瓦尔特被迫与事件始作俑者去向星门另一侧。；或许连他自己也未曾料到，在那里等待着的，将是全新的旅途和同伴。", "385" },
            new[] { "xueyi", "雪衣", "毁灭", "量子", "仙舟「罗浮」的「十王司」判官之一，负责拘、锁、刑、问的四判官中的「拘」。；手持铁索与破魔锥，不知疲倦地寻索重犯，将其勾摄镇伏。；过去的肉身已灰飞烟灭，借偃偶身躯「还阳」，每缉拿一个凶徒便抵半日。", "374" },
            new[] { "yanqing", "彦卿", "巡猎", "冰", "意气飞扬的云骑骁卫，仙舟「罗浮」最强剑士。；为剑生亦为剑痴，当彦卿手中握剑时，无人敢小看这位尚在总角之年的天才。；或许能让手中宝剑微微收敛锋芒的，只有时间。", "1059" },
            new[] { "yao_guang", "爻光", "欢愉", "物理", "神秘，大胆，激进，求变之举令人瞠目结舌。；以巡猎之「眼」遍观吉凶，明知天意难违，「戎韬将军」仍旧孤身涉险。；这一支下下签，如何能够改运换天？", "624" },
            new[] { "yukong", "驭空", "同谐", "虚数", "仙舟「罗浮」天舶司司舵，性情温和，处事老练。；年轻时作为飞行士久历战阵，以优秀的战绩成为主司，却因一场惨烈的战争不再飞翔天际。；如今虽已褪去锋芒，专心操持公务，但「罗浮」的航向上始终有她的身影。", "613" },
